function JapaneseStoryTaskDialog:InitHandler()
    self._events[Constants.EventNames.JapaneseStoryTaskDraw] = Events.AddListener(Constants.EventNames.JapaneseStoryTaskDraw, Bind(self, self.TaskDrawEventHandler))

