--region handler
---列表刷新
function JapaneseStoryTaskDialog:OnGetItemByIndex(listView, index)
    local luaIndex = index + 1
    local cellData = self:GetTaskList()[luaIndex]
    local cell = listView:NewListViewItem("ActivityJapaneseStoryTaskNode")
    local scr = CfUtils.GetLuaScr(cell, "Game.Activity.JapaneseStory.JapaneseStoryTaskCell")
    scr:Refresh(cellData)
    if luaIndex <= listView.DisplayItemCount then
        CfUtils.PlayDelayShowAnimation(cell, index)
    end
    return cell
end

---一键领取按钮回调
function JapaneseStoryTaskDialog:BtnDrawAllOnClickHandler()
    self:DrawRequest(0)
end

---领取任务奖励事件处理
function JapaneseStoryTaskDialog:TaskDrawEventHandler(taskId)
    self:DrawRequest(taskId)
end

---任务home回调处理
function JapaneseStoryTaskDialog:TaskHomeResponseHandler(request, response)
    table.sort(response.data.tasks, function(a, b)
        local aStatus = checkInt(a.status)
        local bStatus = checkInt(b.status)
        if aStatus == bStatus then
            return checkInt(a.id) < checkInt(b.id)
        else
            if aStatus == 1 then
                return true
            elseif bStatus == 1 then
                return false
            elseif aStatus == 2 then
                return false
            elseif bStatus == 2 then
                return true
            else
                return false
            end
        end
    end)
    self:SetTaskData(response.data)
    self:SetTaskList(self:GetTaskData().tasks)

    -- 更新红点
    local tips = -1
    for i, v in ipairs(self:GetTaskList()) do
        if checkInt(v.status) == 1 then
            tips = 0
            break
        end
    end
    JapaneseStoryMgr:SetTaskTips(tips)
    self:RefreshUI()
end

---任务领取回调处理
function JapaneseStoryTaskDialog:TaskDrawResponseHandler(request, response)
    if checkNumber(response.errCode) ~= 0 then return end

    local jsonData = response.data
    local rewards = checkTable(jsonData.rewards)
    if #rewards > 0 then
        GoodsUtils.DrawRewards(rewards)
        UIModule.OpenDialog({ id = Constants.UITypeIds.UICommonRewardPop, parameters = { rewards = rewards } })
    end

    self:InitData()
end
--endregion handler

--region private
---刷新UI
function JapaneseStoryTaskDialog:RefreshUI()
    local taskCount = table.count(self:GetTaskList())
    if not self.ListView.IsListViewInit then
        self.ListView:InitListView(taskCount, Bind(self, self.OnGetItemByIndex))
        self.ListView:UpdateDisplayItemCount("CellNode")
    else
        GameUtils.ReloadData(self.ListView, taskCount)
    end
end

---领取请求
---@param taskId number 任务id,为空为一键领取
function JapaneseStoryTaskDialog:DrawRequest(taskId)
    local taskList = self:GetTaskList()
    local canDraw = false
    for _, v in ipairs(taskList) do
        if v.status == 1 then
            canDraw = true
            break
        end
    end
    if not canDraw then
        GameUtils.Toast(localize('暂无可领取的奖励'))
        return
    end

    local activityId = JapaneseStoryMgr:GetActivityId()
    GameUtils.Request(Interfaces.JapaneseStoryDrawTask, {activityUuid = activityId, taskId = taskId, type = JapaneseStoryUtils.TaskType.Task}, Bind(self, self.TaskDrawResponseHandler))
end
--endregion private

